	public static function svg(string $name, string $class = ''): string
	{
		$paths = self::PATHS[$name] ?? self::PATHS['info'];
		$cls = 'icon' . ($class !== '' ? ' ' . htmlspecialchars($class, ENT_QUOTES, 'UTF-8') : '');
		return '<svg class="' . $cls . '" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" '
		. 'stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">' . $paths . '</svg>';
	}

	public static function has(string $name): bool
	{
		return isset(self::PATHS[$name]);
	}

	public static function names(): array
	{
		return array_keys(self::PATHS);
	}
}
